<?php
if(getenv('INSTAPASS_ISOLATED_TEST')!=='yes'||!defined('WP_CLI')||!WP_CLI)throw new RuntimeException('Isolated only');
$GLOBALS['ipce_tests']=0;function ipce_test($x,$s){if(!$x)throw new RuntimeException('FAIL '.$s);$GLOBALS['ipce_tests']++;}
function ipce_time($s){return (new DateTimeImmutable($s,wp_timezone()))->getTimestamp();}
$original=ip_ce_config();$groups=array_values(array_filter(ipl_groups(),'ipl_credit'));$claude=$groups[0];$chat=$groups[1];$end=ipce_time('2026-12-01 00:00:00');
foreach([30=>40,28=>40,22=>40,21=>35,15=>35,14=>30,8=>30,7=>25,6=>25,3=>25,2=>20,1=>20] as $days=>$expected){$s=ip_ce_state($end-$days*DAY_IN_SECONDS);ipce_test($s['days']===$days&&(float)$s['percent']===(float)$expected,'Rate boundary '.$days);}
$s=ip_ce_state($end);ipce_test($s['start']===$end&&$s['expiry']==ipce_time('2027-01-01 00:00:00')&&(float)$s['percent']===40.0,'Monthly rollover');$custom=$original;$custom['start_day']=31;$s=ip_ce_state(ipce_time('2027-02-27 12:00:00'),$custom);ipce_test($s['start']===ipce_time('2027-01-31 00:00:00')&&$s['expiry']===ipce_time('2027-02-28 00:00:00'),'February clamp');$s=ip_ce_state(ipce_time('2028-02-29 12:00:00'),$custom);ipce_test($s['start']===ipce_time('2028-02-29 00:00:00')&&$s['expiry']===ipce_time('2028-03-31 00:00:00'),'Leap year clamp');
$valid=ip_ce_validate(['enabled'=>'1','start_day'=>'5','rates'=>[22=>'40',15=>'35',8=>'30',3=>'25',1=>'20']]);ipce_test($valid['start_day']===5,'Owner start day accepted');foreach(['0','32'] as $day){$failed=false;try{ip_ce_validate(['start_day'=>$day]);}catch(InvalidArgumentException $e){$failed=true;}ipce_test($failed,'Invalid owner start day '.$day);}
$GLOBALS['ip_cc_test_front']=true;if(!WC()->session)WC()->initialize_session();if(!WC()->customer)WC()->customer=new WC_Customer(0,true);if(!WC()->cart)WC()->initialize_cart();
foreach([28=>40,21=>35,14=>30,7=>25,3=>25,2=>20,1=>20] as $days=>$percent){$GLOBALS['ip_ce_test_now']=$end-$days*DAY_IN_SECONDS;
 foreach(['USD','GBP','EUR','PKR'] as $cur){$GLOBALS['ip_cc_test_currency']=$cur;
  foreach($groups as $g)foreach($g['offers'] as $face=>$o){$p=wc_get_product($o['id']);$pct=$g['key']==='claude-credits'?$percent:40;$expected=$face*$pct/100;if($cur==='PKR')$expected=floor(($expected*280+50)/100)*100;ipce_test($p->is_purchasable()&&$p->is_in_stock(),$cur.' purchasable '.$face);ipce_test(abs((float)$p->get_price()-$expected)<.001,$cur.' tier price '.$days.' '.$face);$h=ipl_credit_price_html($p,$face);ipce_test(str_contains($h,'data-credit-price-cents="'.(int)round($expected*100).'"')&&!str_contains($h,'/month')&&str_contains($h,'TOOLKIT5'),$cur.' one-time HTML '.$days.' '.$face);}
  WC()->cart->empty_cart();WC()->cart->add_to_cart($claude['offers'][100]['id']);WC()->cart->add_to_cart($chat['offers'][100]['id']);WC()->cart->calculate_totals();ipce_test(WC()->cart->apply_coupon('TOOLKIT5'),$cur.' tier coupon '.$days);WC()->cart->calculate_totals();$expected=($percent+40)*.95*($cur==='PKR'?280:1);ipce_test(abs((float)WC()->cart->get_total('edit')-$expected)<.011,$cur.' tier cart total '.$days);
 }
}
$GLOBALS['ip_cc_test_currency']='USD';$GLOBALS['ip_ce_test_now']=$end-5*DAY_IN_SECONDS;WC()->cart->empty_cart();WC()->cart->add_to_cart($claude['offers'][100]['id']);WC()->cart->calculate_totals();$before=instapass_cc_quote_signature();$p=wc_get_product($claude['offers'][100]['id']);$line=new WC_Order_Item_Product();$line->set_product($p);$values=['data'=>$p,'quantity'=>1];do_action('woocommerce_checkout_create_order_line_item',$line,'test',$values,new WC_Order());$saved=$line->get_meta('_instapass_credit_batch_snapshot');ipce_test($saved['expiry']===$end&&(float)$saved['percent_of_face']===25.0,'Order expiry/rate snapshot');ipce_test($line->get_meta('Credit expiry')===ip_ce_date($end),'Public order expiry snapshot');
$changed=$original;$changed['start_day']=2;update_option('instapass_claude_credit_cycle',$changed,false);WC()->cart->calculate_totals();ipce_test((float)wc_get_product($p->get_id())->get_price()===25.0,'Within-tier price stable after date change');ipce_test($before!==instapass_cc_quote_signature(),'Expiry change invalidates quote');ipce_test($line->get_meta('_instapass_credit_batch_snapshot')===$saved,'Saved order snapshot unchanged');update_option('instapass_claude_credit_cycle',$original,false);
$paused=$original;$paused['enabled']=false;update_option('instapass_claude_credit_cycle',$paused,false);ipce_test(wc_get_product($p->get_id())->get_price()===''&&!wc_get_product($p->get_id())->is_purchasable(),'Paused Claude cannot sell');ipce_test(wc_get_product($chat['offers'][100]['id'])->is_purchasable()&&(float)wc_get_product($chat['offers'][100]['id'])->get_price()===40.0,'ChatGPT unaffected by Claude pause');update_option('instapass_claude_credit_cycle',$original,false);
$GLOBALS['ip_cc_test_front']=false;wp_set_current_user((int)get_users(['role'=>'administrator','number'=>1,'fields'=>'ID'])[0]);ob_start();ip_ce_admin();$html=ob_get_clean();ipce_test(str_contains($html,'name="start_day"')&&str_contains($html,'name="fingerprint"')&&str_contains($html,'ip_ce_save'),'Owner control renders');
WC()->cart->empty_cart();unset($GLOBALS['ip_ce_test_now']);echo wp_json_encode(['result'=>'pass','checks'=>$GLOBALS['ipce_tests'],'no_order_or_email_sent'=>true],JSON_PRETTY_PRINT);
